   27	func (a *API) createReminder(w http.ResponseWriter, r *http.Request) {
   28		u := auth.UserFrom(r.Context())
   29		var req createRequest
   30		if !a.decode(w, r, &req) {
   31			return
   32		}
   33		if strings.TrimSpace(req.Text) == "" {
   34			a.fail(w, http.StatusBadRequest, "text is required")
   35			return
   36		}
   37		priority := 2
   38		if req.Priority != nil {
   39			if *req.Priority > 3 {
   40				a.fail(w, http.StatusBadRequest, "priority must be 1, 2, or 3")
   41				return
   42			}
   43			priority = *req.Priority
   44		}
   45		var (
   46			due  time.Time
   47			rule schedule.Rule
   48			err  error
   49		)
   50		switch {
   51		case req.Every != "":
   52			zone := schedule.LookupZone(cmp.Or(req.TZ, u.Prefs.TZ))
   53			rule, err = schedule.Parse(req.Every, zone, a.Now())
   54		case req.In != "":
   55			var d time.Duration
   56			d, err = duration.Parse(req.In)
   57			due = a.Now().Add(d)
   58		case req.At != "":
   59			due, err = time.Parse(time.RFC3339, req.At)
   60		default:
   61			a.fail(w, http.StatusBadRequest, "one of in, at, or every is required")
   62			return
   63		}
   64		if err != nil {
   65			a.fail(w, http.StatusBadRequest, err.Error())
   66			return
   67		}
   68		if err := quota.CheckReminders(planOf(u), a.Store.Count(u.ID)); err != nil {
   69			a.fail(w, http.StatusForbidden, err.Error())
   70			return
   71		}
   72		rem := a.Store.Create(u.ID, req.Text, due, rule)
   73		if priority != 2 {
   74			err := a.Store.Update(rem.ID, func(r *store.Reminder) error {
   75				r.Priority = priority
   76				return nil
   77			})
   78			if err != nil {
   79				a.writeError(w, err)
   80				return
   81			}
   82		}
   83		a.Search.Add(rem.ID, u.ID, rem.Text)
   84		a.Log.Info("reminder created", "id", rem.ID, "user", u.ID)
   85		w.Header().Set("Location", "/v1/reminders/"+rem.ID)
   86		a.writeJSON(w, http.StatusCreated, map[string]string{"id": rem.ID})
   87	}
